/** Frozen env sentinels. A set value means the caller is an agent CLI. */
export const AGENT_ENV_SENTINELS = [
  "CLAUDECODE",
  "GEMINI_CLI",
  "COPILOT_CLI",
  "PI_CODING_AGENT",
] as const;
